      "path": "specs/sdd-domain-concept-test/security-spec.md",
      "sha256": "cb52e5e4b202cdeeb837c2dbcfe9876652518b02fece635848283c019a87cf44"
    },
    {
      "path": "specs/sdd-domain-concept-test/tasks.md",
      "sha256": "63e4db01e19c91a5aef323d32b9b56048226d517fb01e9a577ee2cd734bb233f"
    },
    {
      "path": "specs/sdd-domain-concept-test/traceability.md",
      "sha256": "f751b5d5282f01e37b196f0668a40152e1e7a6d78a5456c6753b485fc320588d"
    },
    {
      "path": "specs/sdd-domain-concept-test/ux-spec.md",
      "sha256": "9ed375e9bf9cba444885cb4a53caa44346dad2cc962d454c8448951075e52020"
    }
  ],
  "verdict": "PASS",
  "checks": [
    {
      "id": "PREREQ-AC-IDS",
      "status": "PASS",
      "severity": "Critical",
      "finding": "tasks.md Requirements fields reference only REQ-001 through REQ-006; every explicitly claimed AC-001 through AC-018 appears in acceptance-tests.md."
    },
    {
      "id": "BLOCKERS-FORMAT",
      "status": "PASS",
      "severity": "Major",
      "finding": "blockers_format_valid=true. T-001 and T-005 use None; T-002, T-003, T-004, and T-006 use comma-separated valid T-NNN identifiers."
    },
    {
      "id": "REQ-COVERAGE",
      "status": "PASS",
      "severity": "Critical",
      "finding": "requirements.md REQ-001 through REQ-006 are covered by tasks.md Requirements fields: T-001/T-002 cover REQ-001 and REQ-002, T-001/T-003 cover REQ-003, T-003/T-005 cover REQ-004, T-004 covers REQ-005, and T-006 covers REQ-006."
    },
    {
      "id": "AC-COVERAGE",
      "status": "PASS",
      "severity": "Critical",
      "finding": "Every AC-001 through AC-018 has explicit task ownership in tasks.md Scope: T-001 owns AC-001–007 and AC-014–016; T-002 owns AC-008–009; T-003 owns AC-010–011 and AC-017 with end-to-end AC-016 coverage; T-004 owns AC-012 and AC-018; T-005 provides distinct consumer-level AC-010–011 coverage; T-006 owns AC-013."
    },
    {
      "id": "ORPHAN-TASK",
      "status": "PASS",
      "severity": "Major",
      "finding": "Every task T-001 through T-006 has a Requirements field containing at least one existing REQ-NNN identifier."
    },
    {
      "id": "ORPHAN-TEST",
      "status": "PASS",
      "severity": "Major",
      "finding": "Tasks whose titles contain Concept Test or verify explicitly identify acceptance targets in their Scope: T-001 AC-001–007/014–016, T-002 AC-008–009, T-004 AC-012/018, and T-006 AC-013."
    },
    {
      "id": "INITIAL-STATE",
      "status": "PASS",
      "severity": "Major",
      "finding": "Under the declared post-implementation provenance re-review rule, T-001 through T-006 have lifecycle-valid Approval: Approved values; T-001 is In Progress and T-002 through T-006 are Planned."
    },
    {
      "id": "RISK-WORKFLOW-FORMAT",
      "status": "PASS",
      "severity": "Critical",
      "finding": "precheck-result.json records workflow_match_precheck=PASS. High-risk T-001/T-003/T-004 use tdd, and medium-risk T-002/T-005/T-006 use acceptance-first."
    },
    {
      "id": "NO-DUPLICATE-AC",
      "status": "PASS",
      "severity": "Major",
      "finding": "Primary AC ownership is unique. Shared AC-010/011 and AC-016 references have explicitly differentiated consumer, bootstrap-integration, contract-validator, and end-to-end scopes."
    },
    {
      "id": "DEPENDENCY-COMPLETE",
      "status": "PASS",
      "severity": "Major",
      "finding": "Every Blockers reference resolves to one of dependency-graph.json nodes T-001 through T-006."
    },
    {
      "id": "DEPENDENCY-CYCLE",
      "status": "PASS",
      "severity": "Critical",
      "finding": "BLOCKERS-FORMAT passed. Following dependency-graph.json edges from each node reaches terminal T-001 or T-005 without revisiting a node; no cycle exists."
    },
    {
      "id": "SINGLE-CONCERN",
      "status": "PASS",
      "severity": "Major",
      "finding": "Each task has one coherent concern: evidence contract, proposal workflow, bootstrap gate, review-context binding, v2 consumer switch, or release-surface registration. Associated tests and evidence are directly tied to those concerns."
    },
    {
      "id": "OBSERVABLE-DONE",
      "status": "PASS",
      "severity": "Major",
      "finding": "Each Done When item names concrete TEST identifiers, pass/fail behavior, invocation counts, manifest parity, regression results, or non-frozen verification/implementation/quality-gate artifacts. precheck-result.json frozen_artifact_done_when is empty, so no flagged frozen-artifact item requires individual disposition."
    },
    {
      "id": "TRACEABILITY-SYNC",
      "status": "PASS",
      "severity": "Major",
      "finding": "traceability.md maps every REQ-001 through REQ-006 to existing tasks T-001 through T-006, and every task appears in at least one requirement row. Each requirement row cites existing hash-bound ux-spec.md, frontend-spec.md, infra-spec.md, or security-spec.md section anchors."
    }
  ],
  "findings": []
}

